

/*
	-- steps to migrate secondary logshipping database to another disk
	1. change database to no recovery mode - GUI (not standby mode then can update metadata)
	2. update file path metadata with new location
	3. stop sql service 
	4. copy data files to new location
		4.1 Affiliate databases
		4.2 bodb_LicenseeReportArchive
	5. start sql service (optional)
	6. reboot server
*/




/*
select 'ALTER DATABASE ' ,db_name(database_id) dbname,'MODIFY FILE ( NAME = ', '['+name+']',', FILENAME = ''' 
	+ replace(physical_name,'N:\IBC_DB\','G:\IBC_DB\') + ''');' 
	,*
from sys.master_files
--where physical_name like '[mn]%'
where database_id in (db_id('Affiliate_12Bet'),db_id('Affiliate_Aoncash'),db_id('Affiliate_Athena000'),db_id('Affiliate_itcbet'),db_id('Affiliate_Macaubet'),db_id('Affiliate_spondemo'))
